 book:'<path d="M12 5c-3-2-6-2-10-1v16c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v16"/>',
 chat:'<path d="M21 11a8 8 0 0 1-8 8H8l-5 3V11a8 8 0 0 1 8-8h2a8 8 0 0 1 8 8Z"/><path d="M8 10h8m-8 4h5"/>',
 language:'<path d="M3 5h12M9 3v2M5 5c0 6 8 10 8 10M13 5c0 6-8 10-8 10m10 6 4-10 4 10m-6-3h4"/>',
